```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let lines = [];
let lineCount = 0;

rl.on('line', (line) => {
    lines.push(line);
    lineCount++;
    if (lineCount === 1) {
        const parts = line.trim().split(/\s+/).map(Number);
        const n = parts[0];
        const x = parts[1];
        const y = parts[2];

        const dp = new Array(2 * n + 1).fill(0);
        dp[1] = x;

        for (let i = 2; i <= n; i++) {
            dp[i] = Math.min(dp[i - 1] + x, dp[Math.floor((i + 1) / 2)] + y + (i % 2) * x);
            dp[i - 1] = Math.min(dp[i - 1], dp[i] + x);
        }

        console.log(dp[n]);
        rl.close();
    }
});
